-- ===========================================================================
-- Part 2: constraints, RLS, privileges and triggers (hand-written)
-- ===========================================================================

ALTER TABLE "categories"
  ADD CONSTRAINT "categories_name_valid" CHECK (length(btrim("name")) BETWEEN 1 AND 120);

ALTER TABLE "products"
  ADD CONSTRAINT "products_name_valid" CHECK (length(btrim("name")) BETWEEN 1 AND 120),
  -- Uppercase, so SKUs are unique case-insensitively.
  ADD CONSTRAINT "products_sku_format" CHECK ("sku" ~ '^[A-Z0-9][A-Z0-9._-]{0,39}$'),
  ADD CONSTRAINT "products_barcode_format" CHECK ("barcode" ~ '^[0-9A-Za-z-]{4,64}$'),
  ADD CONSTRAINT "products_price_range" CHECK ("price_poisha" BETWEEN 0 AND 1000000000),
  ADD CONSTRAINT "products_cost_range" CHECK ("cost_poisha" BETWEEN 0 AND 1000000000),
  ADD CONSTRAINT "products_vat_rate_range" CHECK ("vat_rate_bp" BETWEEN 0 AND 10000),
  ADD CONSTRAINT "products_low_stock_threshold_range" CHECK ("low_stock_threshold" >= 0);

ALTER TABLE "stock_levels"
  ADD CONSTRAINT "stock_levels_quantity_non_negative" CHECK ("quantity" >= 0);

ALTER TABLE "stock_movements"
  ADD CONSTRAINT "stock_movements_delta_non_zero" CHECK ("quantity_delta" <> 0),
  ADD CONSTRAINT "stock_movements_quantity_after_non_negative" CHECK ("quantity_after" >= 0),
  -- Receipts add stock, sales remove it; adjustments go either way but need a reason.
  ADD CONSTRAINT "stock_movements_direction" CHECK (
    ("type" IN ('opening', 'purchase', 'sale_void', 'return') AND "quantity_delta" > 0)
    OR ("type" = 'sale' AND "quantity_delta" < 0)
    OR "type" = 'adjustment'
  ),
  ADD CONSTRAINT "stock_movements_adjustment_reason" CHECK (
    "type" <> 'adjustment' OR length(btrim(coalesce("reason", ''))) >= 3
  );

-- Row Level Security: tenant isolation on every new table.
ALTER TABLE "categories" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "categories" FORCE ROW LEVEL SECURITY;
CREATE POLICY "categories_tenant_isolation" ON "categories"
  USING ("tenant_id" = app_current_tenant_id())
  WITH CHECK ("tenant_id" = app_current_tenant_id());

ALTER TABLE "products" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "products" FORCE ROW LEVEL SECURITY;
CREATE POLICY "products_tenant_isolation" ON "products"
  USING ("tenant_id" = app_current_tenant_id())
  WITH CHECK ("tenant_id" = app_current_tenant_id());

ALTER TABLE "stock_levels" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "stock_levels" FORCE ROW LEVEL SECURITY;
CREATE POLICY "stock_levels_tenant_isolation" ON "stock_levels"
  USING ("tenant_id" = app_current_tenant_id())
  WITH CHECK ("tenant_id" = app_current_tenant_id());

ALTER TABLE "stock_movements" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "stock_movements" FORCE ROW LEVEL SECURITY;
CREATE POLICY "stock_movements_tenant_isolation" ON "stock_movements"
  USING ("tenant_id" = app_current_tenant_id())
  WITH CHECK ("tenant_id" = app_current_tenant_id());

-- Privileges. Default privileges gave app_user full DML on the new tables; narrow it:
-- stock levels are written only by the trigger below, movements are append-only,
-- and products are archived rather than deleted.
REVOKE INSERT, UPDATE, DELETE ON "stock_levels" FROM app_user;
REVOKE UPDATE, DELETE ON "stock_movements" FROM app_user;
REVOKE DELETE ON "products" FROM app_user;

-- Applies each movement to its stock level, atomically, under a row lock:
-- creates the level at 0 if needed, refuses to go below zero, and records the
-- resulting quantity on the movement. Runs as the table owner (SECURITY DEFINER),
-- because app_user cannot write stock_levels; FORCE ROW LEVEL SECURITY still
-- applies to the owner, so the session's tenant context is enforced.
CREATE FUNCTION apply_stock_movement() RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public, pg_temp
AS $$
DECLARE
  current_quantity integer;
  new_quantity integer;
BEGIN
  INSERT INTO stock_levels (tenant_id, branch_id, product_id, quantity, updated_at)
  VALUES (NEW.tenant_id, NEW.branch_id, NEW.product_id, 0, now())
  ON CONFLICT (tenant_id, branch_id, product_id) DO NOTHING;

  SELECT quantity INTO current_quantity
  FROM stock_levels
  WHERE tenant_id = NEW.tenant_id AND branch_id = NEW.branch_id AND product_id = NEW.product_id
  FOR UPDATE;

  IF current_quantity IS NULL THEN
    RAISE EXCEPTION 'stock_level_not_visible' USING ERRCODE = 'P0001';
  END IF;

  new_quantity := current_quantity + NEW.quantity_delta;
  IF new_quantity < 0 THEN
    RAISE EXCEPTION 'insufficient_stock'
      USING ERRCODE = 'P0001', DETAIL = format('available=%s', current_quantity);
  END IF;

  UPDATE stock_levels
  SET quantity = new_quantity, updated_at = now()
  WHERE tenant_id = NEW.tenant_id AND branch_id = NEW.branch_id AND product_id = NEW.product_id;

  NEW.quantity_after := new_quantity;
  RETURN NEW;
END;
$$;

CREATE TRIGGER "stock_movements_apply"
  BEFORE INSERT ON "stock_movements"
  FOR EACH ROW EXECUTE FUNCTION apply_stock_movement();

-- A product's unit is fixed once stock has moved: existing quantities are in that
-- unit's base units, so changing it would silently reinterpret them.
CREATE FUNCTION prevent_unit_change_after_movements() RETURNS trigger
  LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.unit IS DISTINCT FROM OLD.unit AND EXISTS (
    SELECT 1 FROM stock_movements WHERE tenant_id = OLD.tenant_id AND product_id = OLD.id
  ) THEN
    RAISE EXCEPTION 'product_unit_locked' USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER "products_unit_lock"
  BEFORE UPDATE OF "unit" ON "products"
  FOR EACH ROW EXECUTE FUNCTION prevent_unit_change_after_movements();
